def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    minimum = min(values)
    maximum = max(values)
    value = maximum - minimum
    return {
        "value": value,
        "trace": {
            "values": values,
            "minimum": minimum,
            "maximum": maximum,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
